INSERT INTO _seed_neuro_a1_context (unit_id,topic_id,actor_id) SELECT cu.id,COALESCE((SELECT id FROM quiz_topics WHERE curricular_unit_id=cu.id AND title='Aula 1 - Introdução ao estudo de Neuroanatomia' LIMIT 1),'quiz-topic-neuro-aula-1'),actor.id FROM curricular_units cu CROSS JOIN _seed_neuro_a1_actor actor WHERE cu.code='NEURO' AND cu.active=1;
