INSERT INTO quiz_topics (id,curricular_unit_id,title,description,status,sort_order,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT topic_id,unit_id,'Aula 1 - Introdução ao estudo de Neuroanatomia','Descrição geral do sistema nervoso central: encéfalo, espinal medula, organização funcional e sistema ventricular.','published',1,unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,title=excluded.title,description=excluded.description,status='published',published_at=COALESCE(quiz_topics.published_at,excluded.published_at),published_by=COALESCE(quiz_topics.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-a1-026',unit_id,topic_id,'Os feixes ascendentes e descendentes da substância branca medular asseguram:',NULL,'Os feixes da substância branca ligam segmentos da espinal medula entre si e estabelecem vias ascendentes e descendentes com o cérebro. Não são vias comissurais hemisféricas nem estruturas secretoras.','easy','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=excluded.image_url,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
