INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-a1-043',unit_id,topic_id,'Que função desempenha a estrutura alongada assinalada superiormente no corte mediano do cérebro?','/quiz-images/neuro/aula-1/page-007-figure-2.jpeg','A estrutura é o corpo caloso, a maior comissura cerebral. As suas fibras cruzam a linha média e ligam regiões correspondentes dos dois hemisférios; as fibras de projeção para níveis inferiores percorrem, entre outras vias, a cápsula interna.','easy','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_a1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=excluded.image_url,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
